mapper.select:
INSERT INTO iam_column_permission_template (
    tenant_id, code, name, description, is_enabled, created_by, updated_by
)
VALUES (
    #{tenantId}, #{code}, #{name}, #{description}, #{enabled}, #{operator}, #{operator}
)
RETURNING id

mapper.insert:
INSERT INTO iam_column_permission_template_item (
    template_id, resource_column_id, access_mode, created_by, updated_by
)
VALUES (
    #{templateId}, #{resourceColumnId}, #{accessMode}, #{operator}, #{operator}
)

mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM iam_tenant_column_permission_template_assignment assignment
    JOIN iam_column_permission_template template ON template.id = assignment.template_id
    WHERE assignment.tenant_id = #{tenantId}
      AND assignment.template_id = #{templateId}
      AND assignment.deleted_at IS NULL
      AND template.deleted_at IS NULL
      AND template.is_enabled = true
)

mapper.insert:
INSERT INTO iam_tenant_column_permission_template_assignment (
    tenant_id, template_id, is_default, created_by, updated_by
)
VALUES (
    #{tenantId}, #{templateId}, #{defaultTemplate}, #{operator}, #{operator}
)

INSERT INTO iam_role_column_permission_rule (
    tenant_id, role_id, resource_column_id, access_mode, created_by, updated_by
)
VALUES (
    #{tenantId}, #{roleId}, #{resourceColumnId}, #{accessMode}, #{operator}, #{operator}
)

INSERT INTO iam_role_column_permission_template_binding (
    tenant_id, role_id, template_id, created_by, updated_by
)
VALUES (
    #{tenantId}, #{roleId}, #{templateId}, #{operator}, #{operator}
)
